/**
 * The native transport's addon (ADR 0226, T1a.6): the Rust loopback listener and the sockets it
 * opens, as `ace-daemon-node/src/transport.rs` exports them. This module names them and loads
 * them lazily; importing it never touches the binary, so a run with `ACE_TRANSPORT` unset needs no
 * build. The first `transportAddon()` call loads `ACE_TRANSPORT_ADDON`, else `ACE_STORE_ADDON`,
 * else the development build, and a missing file throws naming the path.
 *
 * The hop secret `NativeLoopback.start` takes is this boot's, generated by the OS CSPRNG: it stays
 * in memory, is passed back to `start`, and is never logged, written or published here.
 */
import { appendFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { transportParts } from "./native-switches.ts";
import { warnSafely } from "./native-process.ts";
import type {
  NativeHandled,
  NativeRemoteClass,
  NativeLoopbackClass,
  TransportAddon,
} from "./native-transport-types.ts";

export type {
  TransportDecision,
  TransportAdmitRequest,
  TransportAdmitAnswer,
  TransportStartOptions,
  NativeSocketEvent,
  NativeSendResult,
  NativeSocketHandle,
  NativeLoopbackHandle,
  NativeHandled,
  NativeRemoteLimits,
  NativeRemoteStartOptions,
  NativeRemoteHandle,
  NativeRemoteClass,
  NativeLoopbackClass,
  TransportAddon,
} from "./native-transport-types.ts";

const library =
  process.platform === "win32"
    ? "ace_daemon_node.dll"
    : process.platform === "darwin"
      ? "libace_daemon_node.dylib"
      : "libace_daemon_node.so";

/** The addon: `ACE_TRANSPORT_ADDON`, else `ACE_STORE_ADDON`, else the development build. */
function transportAddonPath(): string {
  const explicit = process.env.ACE_TRANSPORT_ADDON ?? process.env.ACE_STORE_ADDON;
  if (explicit) return explicit;
  return fileURLToPath(
    new URL(`../../../native/daemon/target/release/${library}`, import.meta.url),
  );
}

/** Whether an exported value is the addon's `NativeLoopback` class, statics included. */
function isNativeLoopbackClass(value: unknown): value is NativeLoopbackClass {
  if (typeof value !== "function") return false;
  // A constructor's own static methods, read as a map once its type is checked.
  const statics = value as unknown as Record<string, unknown>;
  return (
    typeof statics["generateSecret"] === "function" &&
    typeof statics["start"] === "function" &&
    typeof statics["underflowCount"] === "function"
  );
}

/** Whether an exported value is the addon's `NativeRemote` class, statics included. */
function isNativeRemoteClass(value: unknown): value is NativeRemoteClass {
  if (typeof value !== "function") return false;
  const statics = value as unknown as Record<string, unknown>;
  return typeof statics["checkIdentity"] === "function" && typeof statics["start"] === "function";
}

/** The fields node puts on a failed `listen`, as `bind_rejection` hands them over. */
interface BindFailureFields {
  code: string;
  errno: number;
  syscall: string;
  address: string;
  port: number;
  message: string;
}

/** Those fields, checked before a JavaScript error takes them. */
function bindFailureFields(value: unknown): BindFailureFields | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const fields = value as Record<string, unknown>;
  if (
    typeof fields["code"] !== "string" ||
    typeof fields["errno"] !== "number" ||
    typeof fields["syscall"] !== "string" ||
    typeof fields["address"] !== "string" ||
    typeof fields["port"] !== "number" ||
    typeof fields["message"] !== "string"
  )
    return undefined;
  return {
    code: fields["code"],
    errno: fields["errno"],
    syscall: fields["syscall"],
    address: fields["address"],
    port: fields["port"],
    message: fields["message"],
  };
}

/** The OS code a failed bind or start carries, or `unknown` when it names none. */
export function transportFailureCode(error: unknown): string {
  if (typeof error !== "object" || error === null) return "unknown";
  const code = Reflect.get(error, "code");
  return typeof code === "string" ? code : "unknown";
}

/**
 * A listener start's failure as node's `listen` reports it. The binding writes the errno's name
 * (`EADDRINUSE`, `EACCES`, `EADDRNOTAVAIL`, ...), node's `errno`, the call and the address as JSON
 * in the error's message, since napi's error can carry only its status as `code`; here it becomes
 * a real Error with those fields, so a caller that branches on `error.code` sees node's answer.
 * Anything that is not one of those payloads is returned untouched.
 */
function bindFailure(error: unknown): unknown {
  if (!(error instanceof Error)) return error;
  let decoded: unknown;
  try {
    decoded = JSON.parse(error.message);
  } catch {
    return error;
  }
  const fields = bindFailureFields(decoded);
  if (fields === undefined) return error;
  const failure = Object.assign(new Error(fields.message), fields);
  return failure;
}

/** The addon's class with its statics kept, its start's bind failure in node's shape. */
function nodeShaped(loopback: NativeLoopbackClass): NativeLoopbackClass {
  return {
    generateSecret: () => loopback.generateSecret(),
    start: async (options, admit, release, opened) => {
      try {
        return await loopback.start(options, admit, release, opened);
      } catch (error) {
        throw bindFailure(error);
      }
    },
    underflowCount: () => loopback.underflowCount(),
  };
}

/** The remote class with its statics kept, its start's bind failure in node's shape. */
function remoteShaped(remote: NativeRemoteClass): NativeRemoteClass {
  return {
    checkIdentity: (cert, key) => remote.checkIdentity(cert, key),
    start: async (options, admit, release, opened, error) => {
      try {
        return await remote.start(options, admit, release, opened, error);
      } catch (failure) {
        throw bindFailure(failure);
      }
    },
  };
}

let loaded: TransportAddon | undefined;

/**
 * The transport addon, loaded on its first call only. A caller asks for it only while
 * `transportParts()` names `loopback`, so the switch-off path never opens the binary; with the
 * switch on and no addon this throws naming the path, before anything starts listening.
 */
export function transportAddon(): TransportAddon {
  if (loaded) return loaded;
  if (!transportParts().has("loopback"))
    throw new Error("Native transport is off: ACE_TRANSPORT names no loopback listener");
  const path = transportAddonPath();
  if (!existsSync(path))
    throw new Error(
      `ACE_TRANSPORT=native needs the transport addon at ${path}; build it with cargo build --release in native/daemon`,
    );
  const module = { exports: {} as Record<string, unknown> };
  process.dlopen(module, path);
  // The addon this tree built, checked for the class and statics
  // `ace-daemon-node/src/transport.rs` declares before anything uses them.
  const loopback = module.exports["NativeLoopback"];
  if (!isNativeLoopbackClass(loopback))
    throw new Error(
      `The transport addon at ${path} exports no NativeLoopback class with generateSecret, start and underflowCount; rebuild it with cargo build --release in native/daemon`,
    );
  const remote = module.exports["NativeRemote"];
  loaded = {
    NativeLoopback: nodeShaped(loopback),
    ...(isNativeRemoteClass(remote) ? { NativeRemote: remoteShaped(remote) } : {}),
  };
  return loaded;
}

/**
 * The addon's `NativeRemote` class. A build of this tree has it; an older addon with only the
 * loopback listener throws here, naming its path, before anything binds.
 */
export function nativeRemoteClass(): NativeRemoteClass {
  const remote = transportAddon().NativeRemote;
  if (remote === undefined)
    throw new Error(
      `The transport addon at ${transportAddonPath()} exports no NativeRemote class; rebuild it with cargo build --release in native/daemon`,
    );
  return remote;
}

/** A native listener's name in the evidence file. */
export type TransportListenerName = "loopback" | "remote";

/** A set of counters, as every handled line carries them. */
export type TransportCounts = NativeHandled;

/** One live listener the evidence helper flushes (T1b.1b); never read by logic. */
interface EvidenceListener {
  listener: TransportListenerName;
  port: number;
  /** This listener's own id in the evidence file, unique within this process. */
  instance: number;
  counts(): NativeHandled;
  /** The counts already written for this listener, so a line holds only the change. */
  written: NativeHandled;
}

/**
 * The id the next native listener gets in the evidence file (T1b.5). A listener is one instance
 * from its bind to its close, so two listeners on the same port in turn are never confused.
 */
let instances = 0;

/** Created only when `ACE_TRANSPORT_EVIDENCE` names a file. */
let evidence: Set<EvidenceListener> | undefined;

/** The evidence file, when the daemon was started to write one. */
function evidencePath(): string | undefined {
  const path = process.env.ACE_TRANSPORT_EVIDENCE;
  return path === undefined || path === "" ? undefined : path;
}

/** One line appended to the evidence file; a failed write is reported, never fatal. */
function appendEvidence(path: string, line: object): void {
  try {
    appendFileSync(path, `${JSON.stringify(line)}\n`);
  } catch (error) {
    warnSafely(`ACE_TRANSPORT_EVIDENCE could not be appended at ${path}: ${String(error)}`);
  }
}

/**
 * A native listener bound on `port` (T1b.1b). The line proves a bind and nothing else; what the
 * listener handled is the close line's, or a `flushTransportEvidence()` line's. Returns this
 * listener's instance id, which its every later line carries.
 */
export function noteTransportStart(listener: TransportListenerName, port: number): number {
  instances += 1;
  const path = evidencePath();
  if (path !== undefined)
    appendEvidence(path, {
      pid: process.pid,
      listener,
      port,
      instance: instances,
      event: "bind",
      backend: "native",
    });
  return instances;
}

/**
 * One lifecycle line for a native listener: `bind-failed` (the requested port and the OS code),
 * `close-requested` (`bound` says whether the bind had landed, and `instance` is absent when it
 * had not) or `close` (with the counts). A line of a bound listener carries its `instance`.
 */
export function noteTransportEvent(
  listener: TransportListenerName,
  port: number,
  event: "bind-failed" | "close-requested" | "close",
  fields: object = {},
): void {
  const path = evidencePath();
  if (path === undefined) return;
  appendEvidence(path, { pid: process.pid, listener, port, event, backend: "native", ...fields });
}

/**
 * Adds a live native listener to the evidence registry, so `flushTransportEvidence()` can say what
 * it handled since its last line. Returns the function that ends it, called once it closed.
 */
export function registerTransportListener(
  listener: TransportListenerName,
  port: number,
  instance: number,
  counts: () => NativeHandled,
): () => void {
  if (evidencePath() === undefined) return () => {};
  const entry: EvidenceListener = { listener, port, instance, counts, written: counts() };
  (evidence ??= new Set()).add(entry);
  return () => {
    evidence?.delete(entry);
  };
}

/**
 * Appends one `handled` line per live native listener with the counts since its last line
 * (T1b.5's case markers call it, so traffic lands in the case that made it). Nothing happens unless
 * `ACE_TRANSPORT_EVIDENCE` names a file.
 */
export function flushTransportEvidence(): void {
  const path = evidencePath();
  if (path === undefined || evidence === undefined) return;
  for (const entry of evidence) {
    const current = entry.counts();
    const counted: NativeHandled = {
      connections: current.connections - entry.written.connections,
      exchanges: current.exchanges - entry.written.exchanges,
      upgrades: current.upgrades - entry.written.upgrades,
      trustedHandshakes: current.trustedHandshakes - entry.written.trustedHandshakes,
      postQuantumHandshakes: current.postQuantumHandshakes - entry.written.postQuantumHandshakes,
      deflatedOut: current.deflatedOut - entry.written.deflatedOut,
      inflatedIn: current.inflatedIn - entry.written.inflatedIn,
    };
    entry.written = current;
    appendEvidence(path, {
      pid: process.pid,
      listener: entry.listener,
      port: entry.port,
      instance: entry.instance,
      event: "handled",
      backend: "native",
      ...counted,
    });
  }
}

let underflowReported = false;

/**
 * `ace-transport`'s unpaired-debit count: non-zero means the crate released a delivery charge it
 * never took, which is its bookkeeping bug and never the peer's. The shell reads it at a socket's
 * close and says so once, through the same warning path the supervisor uses.
 */
export function warnTransportUnderflow(): void {
  if (underflowReported) return;
  let count: number;
  try {
    count = transportAddon().NativeLoopback.underflowCount();
  } catch {
    // The addon is not loaded, or has ended with the listener: nothing to report.
    return;
  }
  if (count === 0) return;
  underflowReported = true;
  warnSafely(
    `native transport: ${count} delivery charge${count === 1 ? "" : "s"} released with nothing to take; this is an ace-transport bug`,
  );
}
